// Fish Identification Quiz: the species records (data/fish-id/species.json,
// generated by scripts/fish-id/import-inat.ts). Server-side only: the list is
// large, so pages pass the set they need to client components as props.

import data from "../../data/fish-id/species.json" with { type: "json" };
import type { SpeciesSet } from "./sets.ts";
import type { Fish } from "./types.ts";

export type { Fish, FishImage, SetId } from "./types.ts";

export const SPECIES: readonly Fish[] = data.species as Fish[];

export function speciesIn(set: SpeciesSet): Fish[] {
  return SPECIES.filter((fish) => fish.sets.includes(set.id));
}
